export function translate(text, language = getPreferences().language) {
  return translations[text]?.[language] || text;
}

export function useTranslation() {
  const [language, setLanguage] = useState(() => getPreferences().language);
  useEffect(() => {
    const update = () => setLanguage(getPreferences().language);
    window.addEventListener("preferences-updated", update);
    window.addEventListener("storage", update);
    return () => {
      window.removeEventListener("preferences-updated", update);
      window.removeEventListener("storage", update);
    };
  }, []);
  useEffect(() => {
    document.documentElement.lang = {
      English: "en", Hindi: "hi", Bengali: "bn", Marathi: "mr",
      Punjabi: "pa", Tamil: "ta", Telugu: "te",
    }[language] || "en";
  }, [language]);
  const t = useCallback((text) => translate(text, language), [language]);
  return { language, t };
}
